  <script>
    // Cookie Preferences Modal
    const modalOverlay = document.getElementById('modalOverlay');
    const openPreferencesBtn = document.getElementById('openPreferences');
    const closeModalBtn = document.getElementById('closeModal');
    const savePreferencesBtn = document.getElementById('savePreferences');

    function openModal() {
      modalOverlay.classList.add('active');
      document.body.style.overflow = 'hidden';
      closeModalBtn.focus();
    }

    function closeModal() {
      modalOverlay.classList.remove('active');
      document.body.style.overflow = '';
    }

    openPreferencesBtn.addEventListener('click', openModal);
    closeModalBtn.addEventListener('click', closeModal);

    modalOverlay.addEventListener('click', (e) => {
      if (e.target === modalOverlay) {
        closeModal();
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modalOverlay.classList.contains('active')) {
        closeModal();
      }
    });

    savePreferencesBtn.addEventListener('click', () => {
      const preferences = {
        analytics: document.getElementById('analyticsToggle').checked,
        personalization: document.getElementById('personalizationToggle').checked,
        advertising: document.getElementById('advertisingToggle').checked
      };
      console.log('Saving preferences:', preferences);
      localStorage.setItem('cookiePreferences', JSON.stringify(preferences));
      closeModal();
    });

    // Load saved preferences
    const saved = localStorage.getItem('cookiePreferences');
    if (saved) {
      const prefs = JSON.parse(saved);
      document.getElementById('analyticsToggle').checked = prefs.analytics || false;
      document.getElementById('personalizationToggle').checked = prefs.personalization || false;
      document.getElementById('advertisingToggle').checked = prefs.advertising || false;
    }

    // Search form
    document.getElementById('searchForm').addEventListener('submit', (e) => {
      const query = e.target.query.value.trim();
      if (query) {
        console.log('Search initiated for:', query);
      }
    });
  </script>
